INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1035031-me316', 'stk-user5643', 'ME 316', 'info', '{"desc": "انا اشوف هالـ لاب ممتع و حلو مع انه شوي يغث كل اسبوع ريبورتات\n\nالجزء الاول من الكورس عن me 311\n\nالجزء الثاني عن me 315\n\nكل اسبوع تجرب و عليها ريبورت و فيه اقزام عن الفوليد و اخر الترم اقزام عن ال heat transfer\n\nشخصيا استفدت من الكورس كثير\n\nطبعا الريبورتات كلها تحتاج تستخدم الاكسل\n\nما فيه بروجيكت\n\nاللاب عليه ساعه وحده ( زي Pe )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-316-thermofluids-laboratory/120746/2", "user": "user5643", "ts": 1336585234000, "tid": 120746, "pn": 2}}', 1336585234000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1179556-me316', 'stk-metallic', 'ME 316', 'info', '{"desc": "هنا تيبلز الاكسل فقط وليست الريبورتات ، بتفيدك اذا بلشت وما عرفت تعوض بالقوانين …\n\nأكيد أن فيها أخطاء وأكيد أن فيها نقص ، ومسؤوليتك أنت أنك تشيك عالمعلومات اللي فيها …\n\nأسأل الله لكم التوفيق … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-316-thermofluids-laboratory/120746/3", "user": "METALLIC", "ts": 1360437249000, "tid": 120746, "pn": 3}}', 1360437249000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1378204-me316', 'stk-user4626', 'ME 316', 'info', '{"desc": "اللاب ينقسم قسمين\nالاول حق مادة me311\nو الثاني me315\nالجزء الأول اسهل من الثاني و ما يخذ وقت ابدا\nالثاني ما هو صعب لكن احيانا التجارب تطول و يبدأ الزهق\nطبعا غالبية الريبورتات تحتاج اكسل يعني لو ما تعرف للاكسل شوف لك حل و تعلم\nالكورس كورس قريد\nيعني A الواحد يخذها بالراحة بس يحتاج شوية حرص", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-316-thermofluids-laboratory/120746/4", "user": "user4626", "ts": 1402199852000, "tid": 120746, "pn": 4}}', 1402199852000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5643-me316', 'stk-user5643', 'ME 316', 'doc', '{"docs": [{"id": "stk-dr-f103290", "n": "Dr. Abdulrahman Al-Murbati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 316 Term 111\n\nالتحضير :\nبداية الاب … ما يحب التاخير بس يسلك\nطريقة الشرح :\nيشرح النظريه اول بعدين يحط القوانين المهمه\nالكويزات :\nلا يوجد\nالمياجر:\nفاينال فلويد & فاينال heat … تختار التجربه بالقرعه … يحذف التجارب الغثيثه من الفاينال … و يكون جزء نظري و جزء عملي\nالقريد النهائي:\nالله يسعده بس … الله يسعده و يوفقه … مو مثل بعض الدكاتره قريد مجحف\nقريد مرضي و يعطيك اكثر من حقك\nالصوت:\nواضح\nإضافات :\nمدرس حبيب و اخلاق … دفعة 2004 … يحضر الماستر و اظن انتهى منه السمستر الماضي …\n\nالحمدلله انه معيد بالقسم خذ معه وانت مغمض …\n\nما كان يطلب شغلات صعبه ب الريبروت ولا يطلب صور ولا فلسفه زايده\n\nsample of calculations & excel tables & conclusion\n\nطبعا لازم ال داتا تكون نفسها اللي اعطاك اياه بالاب … ما ينفع تاخذ ريبورت قديم يعني 🙂\n\nانتبه و انت تكتب ال conclusion لانه يدقق فيها\n\nانصحك خذ معه اي كورس ولا تفوته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047447-me316", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-murbati/103290/6", "user": "user5643", "ts": 1338290178000, "tid": 103290, "pn": 6}}]}', 1338290178000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5430-me316', 'stk-user5430', 'ME 316', 'doc', '{"docs": [{"id": "stk-dr-f103290", "n": "Dr. Abdulrahman Al-Murbati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 316 - ترم 121\n\nالتحضير :\nيوميآ بداية اللاب\n\nطريقة الشرح :\nيشرح ثيوري , وبعدها نسوي التجربة مرة وحدة\n\nالفاينلات :\nفيه فاينلين في المادة , فاينل فلويد وفاينل هيت\nتختار بالقرعة وتسوي التجربة لحالك\n\nالقريد النهائي:\nاممممممممممممممم , يستاهل B+\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور حبيب و شبابي وجيد , لكن اذكر مرة جيته باكسكيوز\nورفض يعيد لي التجربة , ورفض يخليني اكتب الريبورت\nلان ماعاد فيه قروبات يسوونها بهذاك الاسبوع , والريبورت كان عليه 4 % من الكورس\nيعني قريد كامل 🤠\nبالاضافة الى ان تصحيحه شديد بالريبورتات …\nعموما هو بالاخخير دفنا أبد قريد , وماقصر صراحة 🌹\nفي النهاية هو دكتور جيد و حبيب , 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1162433-me316", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-murbati/103290/10", "user": "user5430", "ts": 1357934428000, "tid": 103290, "pn": 10}}]}', 1357934428000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amat_24-me316', 'stk-amat_24', 'ME 316', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^^^^\n\nشبه متاكد انه اسمه كان سعد بن منصور، وليس العكس!\n\n------------------------------------------------\n\nCourse: ME316 - Thermofluids Lab\nSemester: 102\n\nطريقة الشرح :\nممتازة، ما يبدا يشرح في التجربة الا بعد ما يمر على الثيوري كامل\nفادنا لانه الكورس ينزل مع الـ315، والواحد يكون نسي جزء كبير من الفلود (me311)\n\nمن احسن الاشياء فيه انه لازم يحل معانا على الاقل نقطة او اثنين من الداتا\nاللي اقصده، دايما الداتا تكون على شكل جدول، 5 قرائات او اكثر. في اللاب، الدكتور يطلع معانا النواتج كلها لاحد القرائات، يعني اذا ركزت وكتبت معاه، باذن الله ما يوقفك شي في البيت\n\nالريبورتس:\nما يقبلها الا بخط اليد. الكمبيوتر تستعمله عشان تسوي فيه الجداول او ترسم القرافس او تطبع الـcover page\n\nضروري: لا تسلمه اي ربورت الا بعد ما تروح وتصوره وتبقي صورة عندك\nالدكتور ما يرجع ولا ربورت، ودرجتك في الربورتات ما تدري عنها وتحصلها مع الفاينل قريد\nصورة الربورت راح تحتاجها عشان تذاكر للفاينلين\n\nبالنسبة للربورتس: يقبلها في اي وقت! مافيه شي اسمه Deadline!!! كم يخصم على التاخير؟ ما ادري. بس قال لو ما تاخرت كثير ما راح اخصم.\nهذي “الميزة” سببتلي مشكلة، في آخر السمستر رحت له وسلمت 5 ربورتات سوى 🤠 😆\n\nالفاينلات :\nالاول (قسم الfluids) جا جدا سهل\nالثاني (قسم الheat) مستواه متوسط\n\nبالنسبة لاختيار التجارب:\nيحدد كم تجربة ويقول الاختبار راح يجي منهم. تدخل يوم الاختبار تحصل اوراق على الطاولة ويقولك اختار واحدة منهم ، وهذي تكون تجربتك\\اختبارك\n\nدرجتك في الفاينل طبعا ما تدري عنها… مع انه الفاينل الاول في نص السمستر تقريبا، بس ما يعطيك هي\n\nللاسف لاني ما كنت اشيل صورة من الربورتس، تعبت شوية في المذاكرة، بس الحمد لله ما جات صعبة التجارب والاسئلة\n\nإضافات :\nتاخر مررررة عشان يعطينا القريد النهائي (في الرجسترار)\nلكنه ابدا ما قصر، الحمد لله طلعت بقريد ممتاز خلاني اتمنى لو الكورس عليه اكثر من ساعة وحدة\n\nالقريد النهائي:\nA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p971895-me316", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/2", "user": "amat_24", "ts": 1327192770000, "tid": 118632, "pn": 2}}]}', 1327192770000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-turky_al-dossary-me316', 'stk-turky_al-dossary', 'ME 316', 'doc', '{"docs": [{"id": "stk-dr-f118646", "n": "Dr. Medhat Nemitallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME-316 Term 121\n\nالمدرس اخلاق ومتعاون جدا جدا\n\nيعني اللي شفته قدلمي ،، واحد جاب 3 من 4 ،، بسبب رسمة غلط قال له الطالب باعدلها ،، قال المدرس عدلها واعطيك 4 من 4\n\nعادي تجيب الريبورت متاخر يا بنفس اليوم يا في لاب ثاني\n\nالميك اب عنده سهل اذا قلت له سبب ،، بس بشرط انه في لاب من لاباته ،، غير لابه ما جربت 🙂\n\nالميدتيرم لاب ،، والله يا اني انخسفت في القريد ليش ما ادري ،، بس السبب مني\n\nبالعربي :: نزل عنده وتوكل على الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1208871-me316", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/medhat-nemitallah/118646/3", "user": "Turky_Al-Dossary", "ts": 1365695833000, "tid": 118646, "pn": 3}}]}', 1365695833000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-i_bo_da7m-me316', 'stk-i_bo_da7m', 'ME 316', 'doc', '{"docs": [{"id": "stk-dr-f118647", "n": "Dr. Bilal Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بطللللللللللللل جداً جداً جداً … إلى أبعد حـد\n\n^\nبس باقي أنتظر القريد للحين تأخر فيها\n\nالمادة لاب me 316\n\nيشرح كل خطوة مطلوبة منك في الريبورت … الريبورت عليه الوزن الأكبر من المادة\n\nوفيه اكسبرمنت ميد تيرم + فاينال كل واحد عليه 20 %\nسهل نوعاً ما … الدكتور حبيب وخلوق ومحترم جداً ومزوووح لأبعد حد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1161675-me316", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bilal-qureshi/118647/3", "user": "i_Bo_Da7m", "ts": 1357842847000, "tid": 118647, "pn": 3}}]}', 1357842847000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-owheading-me316', 'stk-owheading', 'ME 316', 'doc', '{"docs": [{"id": "stk-dr-f182981", "n": "Dr. Yousif Alkhulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME316-TERM191\n\nالتحضير : بداية اللاب عادة وساعات في النهاية ويقدر ظروف الطالب الي عنده ظروف خلته يتأخر\n\nطريقة الشرح : ممتاز، يشرح ع السبورة ويحفز الطلاب ع المشاركة ويحب النقاشات\nالكويزات : معقولة وحلوة\nالفاينلات : // + تصحيح ممتاز\nالقريد النهائي: A+\nالصوت: ممتاز ولكن اللاب كان مزعج فاللي ورى يعانوا شوي مع الصوت\nإضافات : المحاضر جدًا خلوق ويقدر الظروف ويحاول يطورك ويفيدك قدر الإمكان وتصحيحه وقريدات ممتازة، ولكن ما يتساهل مع النقش أو الغش، سوي الي يبغاه وأبشر بالخير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522611-me316", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yousif-alkhulaifi/182981/3", "user": "OWHEADING", "ts": 1591210158000, "tid": 182981, "pn": 3}}]}', 1591210158000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wil.e-me316', 'stk-wil.e', 'ME 316', 'doc', '{"docs": [{"id": "stk-dr-f182981", "n": "Dr. Yousif Alkhulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME316 - Term 202\n\nبنود التقييم :\n\nالتحضير : نهاية اللاب\nطريقة الشرح : سلايدات\nالكويزات : لا يوجدد\nالمياجر: كان الوضع ميد لبارت 1 وميد لبارت 2 بدون فاينل، والتصحيح الكتروني غالبا وكان يراعي الطلاب كثير في الثنتين بس الافرج رغم كذا نازل\nالفاينلات : لا يوجد\nالقريد النهائي: A+++\nالصوت: واضح وانصح فيه للي يبي يفهم\nتصحيحه والتسليم: بالنسبة لتسليم الريبورتات فهو مرن جدا مع الطلاب اذا محتاجين وقت او لا، والتصحيح للأمانة ما ندري كيف وضعه لان ما صحح الا ريبورتين حاليا والباقين شكله مصححهم بس مو عارض نتايجهم لنا\n\nإضافات : الدكتور خلوق وما ننسى انه كان طالب زينا، وبرضو لسا يكمل دكتوراة ومتعاون جدا مع الطلاب ويحب التفاعل مع الطلاب، فلذلك انصح فيه وبقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529935-me316", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yousif-alkhulaifi/182981/7", "user": "wil.e", "ts": 1620567142000, "tid": 182981, "pn": 7}}]}', 1620567142000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
